            G[k] = [[int(x) for x in r] for r in rows]
    return G

G = load()
input_grid = G['Demo pair 1 input']
output_grid = G['Demo pair 1 output']

def transform(grid):
    rows = len(grid)
    cols = len(grid[0])
    h = rows // 2 - 1
    v = cols // 2

    result = [[grid[r][c] for c in range(cols)] for r in range(rows)]

    # Copy top-right to all other quadrants
    for r in range(h + 1):
        for c in range(v, cols):
            # Top-left (mirror horizontally)
            result[r][cols - 1 - c] = grid[r][c]
            # Bottom-left (mirror vertically from top-left)
            result[rows - 1 - r][cols - 1 - c] = grid[r][c]
            # Bottom-right (mirror vertically from top-right)
            result[rows - 1 - r][c] = grid[r][c]

    # Handle edge rows/cols if odd
    if rows % 2 == 1:
        mid_r = rows // 2
        for c in range(cols):
            result[mid_r][c] = grid[mid_r][c]

    if cols % 2 == 1:
        mid_c = cols // 2
        for r in range(rows):
            result[r][mid_c] = grid[r][mid_c]

    # Clear overlapping cells (center line)
    for r in range(rows):
        for c in range(cols):
            if r < h + 1 and c >= v and r <= rows - 1 - (h + 1) and c <= cols - 1 - v:
                continue
            if (r == mid_r if rows % 2 == 1 else False and (r-1)//2 + 1 == h + 1) or \
               (c == mid_c if cols % 2 == 1 else False and (c-1)//2 + 1 == v):
                if c == mid_c and (rows % 2 == 1 and r == mid_r):
                    result[r][c] = grid[r][c]
                elif r == mid_r and rows % 2 == 1:
                    pass

    return result

